import socket

def parseUDPpacket(data):
    return data.decode('utf-8').split(b' ')


def resolveName(nameToResolve):
    try:
        return socket.gethostbyname(nameToResolve)
    except socket.gaierror:
        return None


def sendResponse(requestIP, record):
    response = f"{record}\n"
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.sendto(response.encode('utf-8'), (requestIP, udp_port))
    sock.close()


def UDPMessaging(udp_ip, udp_port):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    server_socket.bind((udp_ip, udp_port))

    while True:
        data, client_address = server_socket.recvfrom(1024)
        request_data = parseUDPpacket(data)
        if len(request_data) == 3 and request_data[0] == b'request':
            name_to_resolve = request_data[1].decode('utf-8')
            resolved_ip = resolveName(name_to_resolve)
            if resolved_ip is not None:
                sendResponse(client_address[0], resolved_ip)
            else:
                sendResponse(client_address[0], "DNS error")
        elif len(request_data) == 2 and request_data[0] == b'record':
            record = request_data[1].decode('utf-8')
            sendResponse(client_address[0], record)
        else:
            print("Invalid request format")

    server_socket.close()
